mapper.select:

WHERE p.del_flag = '0'

    AND p.project_id = #{projectId}


    AND p.project_name LIKE CONCAT('%', #{projectName}, '%')


    AND p.project_code = #{projectCode}


    AND p.status = #{status}


    AND p.dept_id = #{deptId}


    
        
            AND p.sale_contract_id IS NOT NULL
        
        
            AND p.purchase_contract_id IS NOT NULL
        
        
            AND p.repair_contract_id IS NOT NULL
        
        
            AND p.contract_type = #{contractType}
        
    


    AND (
        p.contract_no LIKE CONCAT('%', #{contractNo}, '%')
        OR p.sale_contract_no LIKE CONCAT('%', #{contractNo}, '%')
        OR p.purchase_contract_no LIKE CONCAT('%', #{contractNo}, '%')
        OR p.repair_contract_no LIKE CONCAT('%', #{contractNo}, '%')
    )


    AND p.start_date >= #{params.beginTime}


    AND p.end_date <= #{params.endTime}


ORDER BY p.create_time DESC

mapper.update:
UPDATE sign_project
project_name = #{projectName}, manager_ids = #{managerIds}, manager_names = #{managerNames}, dept_id = #{deptId}, start_date = #{startDate}, end_date = #{endDate}, status = #{status}, description = #{description}, contract_type = #{contractType}, contract_id = #{contractId}, contract_no = #{contractNo}, contract_name = #{contractName}, partner_name = #{partnerName}, sale_contract_id = #{saleContractId}, sale_contract_no = #{saleContractNo}, sale_contract_name = #{saleContractName}, sale_partner_name = #{salePartnerName}, purchase_contract_id = #{purchaseContractId}, purchase_contract_no = #{purchaseContractNo}, purchase_contract_name = #{purchaseContractName}, purchase_partner_name = #{purchasePartnerName}, repair_contract_id = #{repairContractId}, repair_contract_no = #{repairContractNo}, repair_contract_name = #{repairContractName}, repair_partner_name = #{repairPartnerName}, other_file_ids = #{otherFileIds}, update_by = #{updateBy}, update_time = NOW()
WHERE project_id = #{projectId}

