choose.when:
SELECT 'SALE' AS contractType, c.id, c.contract_no AS contractNo, c.contract_name AS contractName, u.unit_name AS partnerName, c.file_id AS fileId FROM psi_contract_sale c LEFT JOIN psi_unit u ON u.id = c.unit_id AND u.deleted = 0 WHERE c.deleted = 0
AND (c.contract_no LIKE CONCAT('%', #{keyword}, '%') OR c.contract_name LIKE CONCAT('%', #{keyword}, '%') OR u.unit_name LIKE CONCAT('%', #{keyword}, '%'))
AND NOT EXISTS ( SELECT 1 FROM sign_project sp WHERE sp.del_flag = '0' AND sp.sale_contract_id = c.id
AND sp.project_id != #{excludeProjectId}
) ORDER BY c.create_time DESC LIMIT 50

SELECT 'PURCHASE' AS contractType, c.id, c.contract_no AS contractNo, c.contract_name AS contractName, u.unit_name AS partnerName, c.file_id AS fileId FROM psi_contract_purchase c LEFT JOIN psi_unit u ON u.id = c.unit_id AND u.deleted = 0 WHERE c.deleted = 0
AND (c.contract_no LIKE CONCAT('%', #{keyword}, '%') OR c.contract_name LIKE CONCAT('%', #{keyword}, '%') OR u.unit_name LIKE CONCAT('%', #{keyword}, '%'))
AND NOT EXISTS ( SELECT 1 FROM sign_project sp WHERE sp.del_flag = '0' AND sp.purchase_contract_id = c.id
AND sp.project_id != #{excludeProjectId}
) ORDER BY c.create_time DESC LIMIT 50

SELECT 'REPAIR' AS contractType, c.id, c.contract_no AS contractNo, c.contract_name AS contractName, cust.unit_name AS partnerName, c.file_id AS fileId FROM eoms_contract c LEFT JOIN psi_unit cust ON cust.id = c.customer_id AND cust.deleted = 0 WHERE c.del_flag = '0'
AND (c.contract_no LIKE CONCAT('%', #{keyword}, '%') OR c.contract_name LIKE CONCAT('%', #{keyword}, '%') OR cust.unit_name LIKE CONCAT('%', #{keyword}, '%'))
AND NOT EXISTS ( SELECT 1 FROM sign_project sp WHERE sp.del_flag = '0' AND sp.repair_contract_id = c.id
AND sp.project_id != #{excludeProjectId}
) ORDER BY c.create_time DESC LIMIT 50

